import sys
from harness import *
import harness
R = []
def check(n, c, d=""): R.append(bool(c)); print(("PASS " if c else "FAIL ") + n + ((" :: " + str(d)) if d and not c else ""))
def main(page, out):
    t = lambda sel: page.inner_text(sel)
    page.click('#tabs [data-v="profile"]'); page.wait_for_selector("#tendList .pftitem"); page.wait_for_selector("#favGrid .favt")
    check("hero has banner, avatar, name and link", all(page.locator(s).count() == 1 for s in ("#profile .pfbanner", "#profile .pfavatar", "#profName", "#profLink")))
    check("counts strip and three tiles (Stats, Chat, Settings)", page.locator("#profile .pfcounts button").count() == 4 and [x.strip() for x in page.locator("#profile .pftile").all_inner_texts()] == ["Stats", "Chat", "Settings"])
    ys = page.evaluate("['#favGrid', '#profBioBox', '#tendList', '#profile .pftiles'].map(s => { const n = document.querySelector(s); return n.hidden ? -1 : n.getBoundingClientRect().top + window.scrollY; })")
    check("order: counts, favourites, stats, bio, then Tendencies, and Stats/Chat/Settings last", ys[0] < ys[2] < ys[3] and (ys[1] == -1 or ys[1] < ys[2]) and page.evaluate("document.querySelector('#profile .pftiles').getBoundingClientRect().top > document.querySelector('#tendList').getBoundingClientRect().top"), ys)
    texts = lambda: page.evaluate("[...document.querySelectorAll('#tendList .pftitem')].map(r => [...r.childNodes].filter(n => !(n.classList && n.classList.contains('pficon'))).map(n => n.textContent).join(''))")   # the line without its little icon
    lines = texts()
    check("anime: loves the top three genres", "Seems to love Comedy/Fantasy/Action" in lines, lines)
    check("anime: hates the genre you rate far below your average", "Seems to hate Thriller" in lines, lines)
    check("anime: tags, ignoring ones you barely have", "Tends to like Male Protagonist/Heterosexual/Female Protagonist" in lines, lines)
    check("anime: format mix", "Mostly TV 68%/Movie 23%/OVA 9%" in lines, lines)
    check("anime: favourite era by decade", "Favourite era is the 2020s (97% of titles)" in lines, lines)
    check("anime: studios you keep coming back to (a studio seen once is ignored)", "Keeps coming back to MAPPA/Madhouse" in lines, lines)
    check("anime: other countries show once they are 10% or more", "Mostly from Japan 90%/Korea 10%" in lines, lines)
    check("anime: time spent watching", "Has spent 43d 1h watching (2,500 episodes)" in lines, lines)
    check("anime: busiest year", "Busiest year: 2023 (100 started)" in lines, lines)
    check("anime: first year recorded", "First recorded watching Anime in 2010" in lines, lines)
    check("anime: completion rate and drop rate", "Ends up completing 88.50% of Anime started" in lines and "Drops 1.8% of what gets started" in lines, lines)
    check("anime: the Planning backlog", "Has 128 titles waiting in Planning" in lines, lines)
    check("the lines are grouped under Taste and Habits", page.locator("#tendList .pfgrp").all_text_contents() == ["Top genres", "Taste", "Habits"], page.locator("#tendList .pfgrp").all_text_contents())
    bars = page.evaluate("[...document.querySelectorAll('#tendList .tgrow')].map(r => [r.querySelector('.tgname').textContent, r.querySelector('.tgval').textContent, Math.round(parseFloat(r.querySelector('.tgbar i').style.width))])")
    check("top 5 genre bars: share of your titles and your average score", [b[0] for b in bars] == ["Comedy", "Fantasy", "Action", "Romance", "Thriller"] and bars[0][1] == "86% · 8.5" and bars[0][2] == 86 and bars[4][1] == "6% · 6.0", bars)
    check("highlighted words are styled", page.locator("#tendList .pfhl").count() == len(lines))
    check("every line has an icon that screen readers skip", page.locator("#tendList .pftitem .pficon[aria-hidden='true']").count() == len(lines))
    page.click('#tendKinds .chip[data-v="manga"]'); page.wait_for_timeout(150)
    ml = texts()
    check("manga tab: reading wording, its own completion rate and chapters read", "First recorded reading Manga in 2010" in ml and "Ends up completing 50.00% of Manga started" in ml and "Has read 8,400 chapters and 300 volumes" in ml, ml)
    check("manga tab: no studios, no drop or planning lines when the stats have none", not any(x.startswith("Keeps coming back") or x.startswith("Drops") or "waiting in Planning" in x for x in ml), ml)
    check("manga tab: origin is always shown", "Mostly from Japan 90%/Korea 10%" in ml, ml)
    check("manga tab selected", page.get_attribute('#tendKinds .chip[data-v="manga"]', "aria-pressed") == "true")
    # favourites
    check("favourites start on anime with 12 covers and Show more (fewer posters, fewer requests)", page.locator("#favGrid .favt").count() == 12 and page.locator("#favMore").is_visible())
    page.click("#favMore"); page.wait_for_function("document.querySelectorAll('#favGrid .favt').length === 24"); page.click("#favMore"); page.wait_for_function("document.querySelectorAll('#favGrid .favt').length === 30")
    check("Show more loads the next 12 each time", ["fav:anime:1", "fav:anime:2", "fav:anime:3"] == [x for x in harness.PROFREQ if x.startswith("fav:anime")] and not page.locator("#favMore").is_visible(), harness.PROFREQ)
    page.locator("#favGrid .favt").first.click(); page.wait_for_selector("#media:not([hidden])")
    check("tapping a favourite title opens it", True); page.evaluate("closeMedia()"); page.wait_for_timeout(200)
    page.click('#favKinds .chip[data-v="characters"]'); page.wait_for_function("document.querySelectorAll('#favGrid .favt').length === 3")
    check("characters filter", "Fav characters 0" in t("#favGrid"), t("#favGrid"))
    page.locator("#favGrid .favt").first.click(); page.wait_for_selector("#media:not([hidden])"); check("tapping a character opens its page", True); page.evaluate("closeMedia()"); page.wait_for_timeout(200)
    page.click('#favKinds .chip[data-v="staff"]'); page.wait_for_function("document.querySelector('#favGrid').textContent.includes('No favourite staff')")
    check("empty filter says so", "No favourite staff yet." in t("#favGrid"))
    page.click('#favKinds .chip[data-v="studios"]'); page.wait_for_function("document.querySelectorAll('#favGrid .favstudio').length === 4")
    check("studios filter shows studio buttons", "Fav Studio 0" in t("#favGrid"))
    page.locator("#favGrid .favstudio").first.click(); page.wait_for_selector("#media:not([hidden])"); check("tapping a studio opens its page", True); page.evaluate("closeMedia()"); page.wait_for_timeout(200)
    page.click('#favKinds .chip[data-v="manga"]'); page.wait_for_function("document.querySelectorAll('#favGrid .favt').length === 2")
    check("manga filter", "Fav manga 0" in t("#favGrid"))
    page.click('#favKinds .chip[data-v="anime"]'); page.wait_for_timeout(150)
    check("going back to a filter does not ask AniList again", len([x for x in harness.PROFREQ if x == "fav:anime:1"]) == 1 and page.locator("#favGrid .favt").count() == 30, harness.PROFREQ)
    # leaving and coming back keeps everything (no new requests)
    n = len(harness.PROFREQ); page.click('#tabs [data-v="pick"]'); page.click('#tabs [data-v="profile"]'); page.wait_for_timeout(400)
    check("reopening Profile reuses what was loaded", len(harness.PROFREQ) == n, harness.PROFREQ[n:])
    check("anime and manga stat cards still fill in", t("#paEps") == "5,100" and t("#pmChaps") == "11,148", (t("#paEps"), t("#pmChaps")))
    page.click('#profile .pftile[data-go="stats"]'); page.wait_for_selector("#stats:not([hidden])"); check("Stats tile opens Stats", True)
    page.click('#tabs [data-v="profile"]'); page.wait_for_selector("#profile:not([hidden])")
    check("narrow width: nothing sticks out sideways", page.evaluate("document.documentElement.scrollWidth <= window.innerWidth + 1"))
out = run(main, viewport=(360, 780))
real = [c for c in out["console"] if "ERR_INTERNET" not in c[1]]
check("no console errors", not real and not out["errors"], (real[:2], out["errors"][:2]))
print("\n%d checks, %d failed" % (len(R), R.count(False))); sys.exit(1 if False in R else 0)
